def priority_encoder(inputs):
    for i in reversed(range(len(inputs))):
        if inputs[i]:
            return i, 1   # code, valid
    return 0, 0            # nothing active

def compare(a, b):
    if a == b: return 'eq'
    return 'gt' if a > b else 'lt'

def nand(a, b):
    if a == 'X' or b == 'X':
        return 'X'      # unknown in, unknown out
    return 0 if (a and b) else 1
